commit 2a07ec0fc72752fe4f3fbc77d4145ae0153f9277
Author: Kenneth Jiang <k@obico.io>
Date:   Tue Sep 22 20:02:32 2026 +0000

    Give printer setup a focused workspace

diff --git a/src/slic3r/GUI/JusPrin/Home/HomeWebView.cpp b/src/slic3r/GUI/JusPrin/Home/HomeWebView.cpp
index 472c7e38c1..3749719f6a 100644
--- a/src/slic3r/GUI/JusPrin/Home/HomeWebView.cpp
+++ b/src/slic3r/GUI/JusPrin/Home/HomeWebView.cpp
@@ -115,6 +115,7 @@ void HomeWebView::attach_side_panel(wxWindow* panel, int width_dip)
     if (m_side_panel != nullptr)
         m_row->Detach(m_side_panel);
     m_side_panel = panel;
+    m_side_panel_width = width_dip;
     if (m_side_panel != nullptr) {
         m_side_panel->SetMinSize(wxSize(FromDIP(width_dip), -1));
         m_row->Add(m_side_panel, 0, wxEXPAND);
@@ -123,11 +124,16 @@ void HomeWebView::attach_side_panel(wxWindow* panel, int width_dip)
     Layout();
 }

-void HomeWebView::show_side_panel(bool shown)
+void HomeWebView::show_side_panel(bool shown, bool focused)
 {
     if (m_side_panel == nullptr)
         return;
     m_side_panel->Show(shown);
+    const bool workspace = shown && focused;
+    m_webview->Show(!workspace);
+    m_error->Show(!workspace && !m_error->GetLabel().empty());
+    m_side_panel->SetMinSize(wxSize(workspace ? 0 : FromDIP(m_side_panel_width), -1));
+    m_row->GetItem(m_side_panel)->SetProportion(workspace ? 1 : 0);
     // The page drops its own printers column while the panel has that place,
     // so the two never both claim it.
     m_host->set_printer_panel_open(shown);
diff --git a/src/slic3r/GUI/JusPrin/Home/HomeWebView.hpp b/src/slic3r/GUI/JusPrin/Home/HomeWebView.hpp
index 5b7f368f75..c55673652a 100644
--- a/src/slic3r/GUI/JusPrin/Home/HomeWebView.hpp
+++ b/src/slic3r/GUI/JusPrin/Home/HomeWebView.hpp
@@ -53,7 +53,8 @@ public:
     // panel is shown, so the two never both claim it. The shell owns the
     // panel's lifetime; passing nullptr takes it back out.
     void attach_side_panel(wxWindow* panel, int width_dip);
-    void show_side_panel(bool shown);
+    // Add uses the whole workspace; existing-printer edits stay beside Home.
+    void show_side_panel(bool shown, bool focused = false);

 private:
     void on_script_message(wxWebViewEvent& event);
@@ -70,6 +71,7 @@ private:
     // row while no panel is attached.
     wxBoxSizer*               m_row{nullptr};
     wxWindow*                 m_side_panel{nullptr};
+    int                       m_side_panel_width{0};
 };

 }}}} // namespace Slic3r::GUI::JusPrin::Home
diff --git a/src/slic3r/GUI/JusPrin/Shell/ShellController.cpp b/src/slic3r/GUI/JusPrin/Shell/ShellController.cpp
index adc7d194d1..1557310ab6 100644
--- a/src/slic3r/GUI/JusPrin/Shell/ShellController.cpp
+++ b/src/slic3r/GUI/JusPrin/Shell/ShellController.cpp
@@ -592,7 +592,7 @@ void ShellController::open_printer_conversation(const std::string& printer_name,
     m_printer_panel->open(connect ? PrinterSetup::ConversationMode::Connect : printer_name.empty() ? PrinterSetup::ConversationMode::Add :
                                                  PrinterSetup::ConversationMode::Change,
                           printer_name);
-    m_home->show_side_panel(true);
+    m_home->show_side_panel(true, printer_name.empty() && !connect);
 }

 void ShellController::on_page_changed()
diff --git a/src/slic3r/GUI/JusPrin/Shell/ShellController.hpp b/src/slic3r/GUI/JusPrin/Shell/ShellController.hpp
index 9914012783..71a213e678 100644
--- a/src/slic3r/GUI/JusPrin/Shell/ShellController.hpp
+++ b/src/slic3r/GUI/JusPrin/Shell/ShellController.hpp
@@ -99,8 +99,8 @@ public:
     // caller passes none.
     void refresh_home(const PrinterSetup::PinnedFacts* added = nullptr);

-    // Opens the printer conversation in place of Home's printers column: an
-    // empty name adds a printer, a name changes that one. From the Prepare
+    // Opens Add in Home's workspace; a named printer uses its side panel.
+    // An empty name adds a printer, a name changes that one. From the Prepare
     // header's printer menu it goes to Home first, since that is where the
     // panel lives. Every opening is a new session.
     void open_printer_conversation(const std::string& printer_name = {}, bool connect = false);

